/** Exact mechanical additions only. The original raw script remains historical input. */
export const CURRENT_VERIFY_ADDITIONS = [
  'bun test ./scripts/check-phase68-active-chain-persistence.test.ts',
  'bun test ./scripts/check-phase165-shared-exact-work.test.ts',
  'bun run scripts/check-phase165-shared-exact-work.ts',
  'run_step "test Phase 68 active chain persistence" bun test ./scripts/check-phase68-active-chain-persistence.test.ts',
  'run_step "test Phase 165 shared exact work" bun test ./scripts/check-phase165-shared-exact-work.test.ts',
  'run_step "check Phase 165 shared exact work" bun run scripts/check-phase165-shared-exact-work.ts',
];

/** Refuse partial/duplicate/reordered additions; every unrelated byte stays pinned. */
export function verificationHistoricalBase(source: string): string {
  const lines = source.split("\n");
  if (!CURRENT_VERIFY_ADDITIONS.some(line => lines.includes(line))) return source;
  if (CURRENT_VERIFY_ADDITIONS.some(line => lines.filter(actual => actual === line).length !== 1)) {
    throw new Error("current verification registrations missing or duplicated");
  }
  const groups = [
    [CURRENT_VERIFY_ADDITIONS[0], 'bun run scripts/check-phase68-active-chain-persistence.ts', true],
    [CURRENT_VERIFY_ADDITIONS[3], 'run_step "check Phase 68 active chain persistence" bun run scripts/check-phase68-active-chain-persistence.ts', true],
    [CURRENT_VERIFY_ADDITIONS.slice(1, 3).join("\n"), 'bun run scripts/check-phase164-canonical-identity.ts', false],
    [CURRENT_VERIFY_ADDITIONS.slice(4).join("\n"), 'run_step "check Phase 164 canonical identity boundary" bun run scripts/check-phase164-canonical-identity.ts', false],
  ] as const;
  let projected = source;
  for (const [addition, anchor, before] of groups) {
    const block = before ? addition + "\n" + anchor : anchor + "\n" + addition;
    if (!projected.includes(block)) throw new Error("current verification registration order changed");
    projected = projected.replace(block, anchor);
  }
  return projected;
}

