/** Exact contextual reviewed fragments only; full immutable destination identity required. */
export function legacyToolingBase(file: string, source: string): string {
  const maybeCurrent = CURRENT_TOOL_WIRING.find(row => row[0] === file);
  const maybeCopied = COPIED_CLI_INVERSES.find(row => row[0] === file);
  let normalized = source;
  if (maybeCopied) {
    const inverse = maybeCopied[1], currentHash = sha(source);
    if (currentHash === COPIED_CLI_ORIGINALS[file]) return source;
    if (currentHash === inverse.currentRawSha) {
      const maybeBefore = maybeRestoreReviewedSource(source, inverse);
      if (maybeBefore === undefined) return source;
      normalized = maybeBefore;
    } else if (currentHash !== inverse.restoredRawSha && currentHash !== maybeCurrent?.[1]) {
      return source;
    }
  }
  let intermediate = normalized;
  if (maybeCurrent && sha(normalized) !== maybeCurrent[1]) {
    if (maybeCurrent[2].some(([current]) => normalized.split(current).length !== 2)) return source;
    for (const [current, previous] of maybeCurrent[2]) intermediate = intermediate.replace(current, () => previous);
    if (sha(intermediate) !== maybeCurrent[1]) return source;
  }
  const maybeWiring = LEGACY_TOOL_WIRING.find(row => row[0] === file);
  if (!maybeWiring) return intermediate;
  if (maybeWiring[2].some(([current]) => intermediate.split(current).length !== 2)) return source;
  let projected = intermediate;
  for (const [current, previous] of maybeWiring[2]) projected = projected.replace(current, previous);
  return sha(projected) === maybeWiring[1] ? projected : source;
}

/** Original receipt qualification only: portable exact-byte snapshots and reviewed raw tooling.
 * Unknown current bytes cannot reuse historical authority, even with a regenerated report.
 */
export function historicalToolingView(sources: ReadonlyMap<string, string>): Map<string, string> {
  if (sha(sources.get(MANIFEST_FILE) ?? "") !== EXPECTED_MANIFEST_SHA) throw new Error("fresh Phase163 VERIFICATION gate/lifecycle/digest: historical tooling manifest changed or missing");
  const manifest = JSON.parse(sources.get(MANIFEST_FILE)!) as {
    bindings: { file: string; snapshot: string; original_sha: string; current_sha: string }[];
  };
  if (JSON.stringify(manifest.bindings.map(row => [row.file, row.snapshot])) !== JSON.stringify(TOOLING_BINDINGS)) {
    throw new Error("historical tooling binding inventory changed");
  }
  const view = new Map(sources);
  for (const [file, inverse] of FILTER_GUARD_INVERSES) {
    const maybeSource = sources.get(file);
    if (maybeSource === undefined) continue;
    const maybeBinding = manifest.bindings.find(row => row.file === file);
    const currentHash = sha(maybeSource);
    if (currentHash === inverse.restoredRawSha || currentHash === maybeBinding?.original_sha) continue;
    const maybeHistorical = maybeRestoreReviewedSource(maybeSource, inverse);
    if (maybeHistorical === undefined) throw new Error(`fresh Phase163 VERIFICATION gate/lifecycle/digest: ${file}: unreviewed current tooling fingerprint`);
    view.set(file, maybeHistorical);
  }
  for (const row of manifest.bindings) {
    const snapshot = sources.get(row.snapshot) ?? "";
    const rawCurrent = view.get(row.file) ?? "";
    const current = row.file === "scripts/verify.sh" ? verificationHistoricalBase(rawCurrent) : legacyToolingBase(row.file, rawCurrent);
    if (sha(snapshot) !== row.original_sha) throw new Error(`fresh Phase163 VERIFICATION gate/lifecycle/digest: ${row.file}: original historical snapshot changed or missing`);
    if (![row.original_sha, row.current_sha].includes(sha(current))) throw new Error(`fresh Phase163 VERIFICATION gate/lifecycle/digest: ${row.file}: unreviewed current tooling fingerprint`);
    view.set(row.file, snapshot);
  }
  return view;
}

/** Make raw/current versus historical aggregate digests visible without relabeling receipts. */
export function toolingAttribution(sources: ReadonlyMap<string, string>, files: readonly string[]): {
  evidence_scope: string; rawCurrentDigest: string; historicalDigest: string; currentOrdinaryQualification: false;
} {
  const digest = (input: ReadonlyMap<string, string>) => sha(files.map(file => `${file}:${sha(input.get(file) ?? "")}`).join("\n"));
  return { evidence_scope: EVIDENCE_SCOPE, rawCurrentDigest: digest(sources), historicalDigest: digest(historicalToolingView(sources)), currentOrdinaryQualification: false };
}
